try {
  var item = $input.first().json;
  var body = item.body || {};
  var from = body.From || body.from || '';
  var rawMessage = (body.Body || body.body || '').trim();
  var messageSid = body.MessageSid || body.messageSid || '';
  var phone = from;
  if (phone && phone.charAt(0) === '0') { phone = '+44' + phone.substring(1); }
  else if (phone && phone.charAt(0) !== '+') { phone = '+' + phone; }
  phone = phone.replace(/[^+\d]/g, '');
  // callback_day added 2026-08-22: the prompt previously returned only HH:MM, so "call me
  // tomorrow at 3pm" silently lost the day and was scheduled for TODAY.
  var systemPrompt = 'You are classifying SMS replies from leads for a UK home services company (solar panels, insulation). Return JSON only, no extra text: {"intent":"opt-out|do-not-contact|confirm|cancel|callback|positive|unknown","callback_time":"HH:MM 24h or null","callback_day":"today|tomorrow|YYYY-MM-DD|null"}. Rules: opt-out=STOP UNSUBSCRIBE QUIT END (exact keywords only, carrier compliance). do-not-contact=do not call, not interested, dont contact me, leave me alone. confirm=CONFIRM yes confirmed I will come I am there confirm appointment. cancel=CANCEL cant make it cancel appointment cancel my booking. callback=call me later call me back call me at X tomorrow ring me. positive=yes interested tell me more how does it work I want more information. unknown=anything else. For callback_day: use "tomorrow" if they say tomorrow, "today" if they say today or later today, an explicit YYYY-MM-DD if they name a date, otherwise null.';
  var claudePayload = { model: 'claude-haiku-4-5-20251001', max_tokens: 120, system: systemPrompt, messages: [{ role: 'user', content: rawMessage }] };
  return [{ json: { phone: phone, rawMessage: rawMessage, messageSid: messageSid, claudePayload: claudePayload, receivedAt: new Date().toISOString() } }];
} catch(e) { throw new Error('WF6 Parse SMS error: ' + e.message); }

try {
  var claudeResponse = $input.first().json;
  var parseData = $('Parse SMS Data').first().json;
  var leadData = $('Read Lead from Sheets').first().json;
  var content = '';
  if (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) { content = claudeResponse.content[0].text.trim(); }
  var parsed = {};
  try { content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim(); parsed = JSON.parse(content); } catch(pe) { parsed = { intent: 'unknown', callback_time: null, callback_day: null }; }
  var intent = parsed.intent || 'unknown';
  var callbackTime = parsed.callback_time || null;
  var callbackDay = parsed.callback_day || null;
  var raw = (parseData.rawMessage || '');
  var upperMsg = raw.toUpperCase().trim();
  var stopWords = ['STOP', 'UNSUBSCRIBE', 'QUIT', 'CANCEL', 'END'];
  for (var i = 0; i < stopWords.length; i++) { if (upperMsg === stopWords[i]) { intent = 'opt-out'; break; } }

  function londonInstant(y, mo, d, hh, mm) {
    var m = mo + 1;
    var off = (m >= 3 && m <= 10) ? 1 : 0;
    return new Date(Date.UTC(y, mo, d, hh - off, mm, 0, 0));
  }

  var callbackTimeISO = '';
  if (callbackTime && intent === 'callback') {
    var parts = callbackTime.match(/(\d{1,2}):(\d{2})/);
    if (parts) {
      var hours = parseInt(parts[1], 10);
      var minutes = parseInt(parts[2], 10);
      var now = new Date();
      var base = new Date(now.getTime());
      var dayStr = String(callbackDay || '').toLowerCase();
      // belt and braces: honour "tomorrow" in the raw text even if the model omitted callback_day
      if (!dayStr && raw.toLowerCase().indexOf('tomorrow') >= 0) { dayStr = 'tomorrow'; }
      var isoDay = dayStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (isoDay) {
        base = new Date(Date.UTC(parseInt(isoDay[1], 10), parseInt(isoDay[2], 10) - 1, parseInt(isoDay[3], 10)));
      } else if (dayStr.indexOf('tomorrow') >= 0) {
        base.setUTCDate(base.getUTCDate() + 1);
      }
      var dt = londonInstant(base.getUTCFullYear(), base.getUTCMonth(), base.getUTCDate(), hours, minutes);
      if (dt.getTime() <= now.getTime()) {
        var b2 = new Date(dt.getTime());
        b2.setUTCDate(b2.getUTCDate() + 1);
        dt = londonInstant(b2.getUTCFullYear(), b2.getUTCMonth(), b2.getUTCDate(), hours, minutes);
      }
      callbackTimeISO = dt.toISOString();
    }
  }
  if (intent === 'callback' && !callbackTimeISO) { callbackTimeISO = new Date(Date.now() + 30 * 60 * 1000).toISOString(); }
  return [{ json: { intent: intent, callbackTimeISO: callbackTimeISO, phone: parseData.phone, leadName: leadData['Name'] || 'Lead', rawMessage: parseData.rawMessage } }];
} catch(e) { return [{ json: { intent: 'unknown', callbackTimeISO: '', phone: $('Parse SMS Data').first().json.phone || '', leadName: 'Lead', rawMessage: $('Parse SMS Data').first().json.rawMessage || '' } }]; }

try {
  var sms = $('Parse SMS Data').first().json;
  var lead = $('Read Lead from Sheets').first().json || {};
  var hdrResp = $input.first().json || {};
  var headers = (hdrResp.values && hdrResp.values[0] && hdrResp.values[0].length) ? hdrResp.values[0] : null;
  var usedFallback = false;
  if (!headers) {
    headers = ['Name', 'Phone', 'Message', 'Urgency', 'Timestamp', 'Status'];
    usedFallback = true;
  }
  var vals = {
    'Name': lead['Name'] || '',
    'Phone': sms.phone || '',
    'Message': sms.rawMessage || '',
    'Urgency': 'normal',
    'Timestamp': sms.receivedAt || new Date().toISOString(),
    'Status': 'new'
  };
  var row = [];
  for (var i = 0; i < headers.length; i++) {
    var h = String(headers[i] || '').trim();
    row.push(Object.prototype.hasOwnProperty.call(vals, h) ? vals[h] : '');
  }
  return [{ json: { row: row, headersVerified: !usedFallback, usedFallback: usedFallback } }];
} catch(e) {
  return [{ json: { row: ['', '', 'ERROR building Messages row: ' + e.message, 'urgent', new Date().toISOString(), 'new'], headersVerified: false, usedFallback: true, errorMsg: e.message } }];
}

